                if embedded_key is not None and embedded_key != configured_key:
                    raise IntegrityKeyMismatch(
                        "configured integrity key does not match the database"
                    )
                resolved = KeyedIntegrityAnchor(configured_key)
            elif embedded_key is not None:
                if len(embedded_key) < _MIN_KEY_BYTES:
                    raise IntegrityConfigurationError(
                        "stored integrity key is unusable"
                    )
                resolved = KeyedIntegrityAnchor(embedded_key)
            else:
