                    # Sidecar exists but deliberately carries no key
                    # (externally provisioned deployment); default
                    # construction must not invent one.
                    raise IntegrityConfigurationError(
                        "database requires an externally configured integrity key"
                    )
                generated = os.urandom(_MIN_KEY_BYTES)
                self._write_sidecar(
                    self._state_path,
                    {"version": _SIDECAR_VERSION, "key": generated.hex(), "heads": {}},
