@staticmethod
def _read_sidecar(path: str) -> dict | None:
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        return None
    except OSError:
        # Unreadable state is treated as structurally broken rather
        # than missing so a later write cannot replace it.
        return {"_unreadable": True, "heads": {}}
    try:
        parsed = json.loads(data.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        return {"_unreadable": True, "heads": {}}
    if not isinstance(parsed, dict):
        return {"_unreadable": True, "heads": {}}
    return parsed

@staticmethod
def _write_sidecar(path: str, state: dict) -> None:
    directory = os.path.dirname(os.path.abspath(path)) or "."
    fd, tmp_path = _mktemp0600(directory)
    try:
        with os.fdopen(fd, "wb") as handle:
            handle.write(
                json.dumps(state, ensure_ascii=True, separators=(",", ":")).encode(
                    "utf-8"
                )
            )
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(tmp_path, path)
    except BaseException:
        with contextlib.suppress(OSError):
            os.unlink(tmp_path)
        raise

def _external_heads(self) -> dict[str, str]:
    """Return the current external head map (fresh read per call)."""
    if self._memory_state is not None:
        return self._memory_state.heads
    state = self._read_sidecar(self._state_path)  # type: ignore[arg-type]
    if state is None or state.get("_unreadable"):
        return {}
    heads = state.get("heads")
    return heads if isinstance(heads, dict) else {}

def _record_external_head(self, domain: str, label: str) -> None:
    """Persist the newly attested head outside SQLite.

    Runs inside the cross-process lock, after the SQLite commit.
    Only tag outputs are written; key material is untouched.
    """
    if self._memory_state is not None:
        self._memory_state.heads[domain] = label
        return
    state = self._read_sidecar(self._state_path)  # type: ignore[arg-type]
    if state is None or state.get("_unreadable") or not isinstance(
        state.get("heads"), dict
    ):
        raise RuntimeError("integrity state is unavailable")
    state["heads"][domain] = label
    self._write_sidecar(self._state_path, state)  # type: ignore[arg-type]

def _migrate_schema(self, conn: sqlite3.Connection) -> None:
    """Add integrity columns to a database written by an older version.

    Additive only: nullable columns and the meta table are created,
    existing rows keep NULL evidence and are never backfilled or
    recomputed. The transactional upgrade runs at most once per file.
    """
    if conn.execute(_REQUEST_CHAIN_COLUMN).fetchone() and conn.execute(
        _REQUEST_ANCHOR_COLUMN
    ).fetchone() and conn.execute(_EVENT_CHAIN_COLUMN).fetchone():
        return
    with self._write_lock:
        try:
            conn.execute("BEGIN IMMEDIATE")
            # Re-probe inside the transaction: another process may
            # have completed the upgrade while we waited on the lock.
            if not conn.execute(_REQUEST_CHAIN_COLUMN).fetchone():
                conn.execute("ALTER TABLE requests ADD COLUMN chain_hash TEXT")
            if not conn.execute(_REQUEST_ANCHOR_COLUMN).fetchone():
                conn.execute("ALTER TABLE requests ADD COLUMN anchor_value TEXT")
            if not conn.execute(_EVENT_CHAIN_COLUMN).fetchone():
                conn.execute(
                    "ALTER TABLE status_events ADD COLUMN chain_hash TEXT"
                )
            conn.execute(_META_TABLE)
            conn.execute("COMMIT")
        except sqlite3.Error:
            try:
                conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise RuntimeError("failed to initialize request store") from None

def _bind_database_key(self, conn: sqlite3.Connection) -> None:
    """Record/check the static key verifier in ``evidence_meta``.

    Stored value is a tag output only, never the key or its preimage.
    A mismatch means the database was initialised with a different
    trust root; refusing writes prevents silently forking the chain.
    """
    verifier = self._anchor.attest(_PURPOSE_KEY_CHECK, (_KEY_CHECK_PART,))
    if self._state_path is not None:
        lock = _file_lock(self._lock_path)  # type: ignore[arg-type]
    else:
        lock = contextlib.nullcontext()
    with lock:
        try:
            conn.execute("BEGIN IMMEDIATE")
            row = conn.execute(
                "SELECT value FROM evidence_meta WHERE domain = ?",
                (_META_KEY_CHECK,),
            ).fetchone()
            if row is None:
                conn.execute(
                    "INSERT INTO evidence_meta (domain, value) VALUES (?, ?)",
                    (_META_KEY_CHECK, verifier),
                )
            elif not self._anchor.verify_attestation(
                _PURPOSE_KEY_CHECK, (_KEY_CHECK_PART,), row[0]
            ):
                conn.execute("ROLLBACK")
                raise IntegrityKeyMismatch(
                    "configured integrity key does not match the database"
                )
            conn.execute("COMMIT")
        except IntegrityConfigurationError:
            raise
        except sqlite3.Error:
            try:
                conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            raise RuntimeError("failed to initialize request store") from None

